procedure PhysioConfirmNewSession {
  about "Confirm a new session and add it to the calendar"
  policy PhysioPolicy
  sheet Sessions "Sessions" { patient: Text, mobile: Phone, session_at: DateTime, therapist: Text, status: Text, injury: Text private }
  calendar Rooms "Rooms"
  trigger when new row r in Sessions

  if r.therapist == "" {
    notify owner "Please update my manager yourself."
    stop "therapist missing"
  }
  let m = draft sms to r.mobile: "Hi {r.patient default 'there'}, your session with {r.therapist} is confirmed for {r.session_at}."
  let ok = request approval of m from owner timeout 1 day else stop "confirmation not approved"
  send ok
  let ev = book Rooms { title: "{r.patient}", at: r.session_at, length: 45 minutes }
  update r set status = "confirmed"
}
