procedure IceRefunds {
  about "Refund deposits below $100; escalate higher ones"
  policy IcePolicy
  sheet PartyCancellations "PartyCancellations" { ref: Text, host: Text, phone: Phone, deposit: Money, party_on: Date }
  trigger when new row r in PartyCancellations

  if days_between(r.party_on, today()) < 3 {
    notify owner "Short-notice cancellation for {r.ref} ({r.deposit}). Please handle it."
    stop "short notice goes to owner"
  }
  if r.deposit > $100.00 {
    notify owner "Deposit of {r.deposit} for {r.ref} is over $100. Please review."
    stop "over $100 goes to owner"
  }
  if r.deposit <= $40.00 {
    refund r.deposit for r.ref reason "party cancellation"
  } else {
    refund r.deposit for r.ref reason "party cancellation", ask owner first timeout 1 day else stop "refund not approved"
  }
  let m = draft sms to r.phone: "Hi {r.host default 'there'}, your deposit of {r.deposit} has been refunded."
  let ok = request approval of m from owner timeout 1 day else stop "message not approved"
  send ok
}
