procedure MoveCancelRefund {
  about "Refund a deposit and cancel the move"
  policy MovePolicy
  sheet MoveCancellations "MoveCancellations" { job: Text, customer: Text, phone: Phone, deposit: Money, move_date: Date }
  trigger when new row r in MoveCancellations

  if r.move_date < today() + 7 days {
    notify owner "Short-notice move cancellation for {r.customer}. Please handle it."
    stop "short notice goes to owner"
  }
  if r.deposit > $200.00 {
    notify owner "Large deposit refund for {r.customer} ({r.deposit}). Please review."
